from fastapi.responses import HTMLResponse
from . import fast_scalper_beta_001_legacy as legacy

HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta http-equiv="Cache-Control" content="no-cache,no-store,must-revalidate"><meta http-equiv="Pragma" content="no-cache"><meta http-equiv="Expires" content="0"><title>Fast Scalper Beta</title><style>
*{box-sizing:border-box}html,body{margin:0;background:#080e1b;color:#edf2ff;font-family:Arial,Helvetica,sans-serif}body{min-width:320px}.wrap{max-width:720px;margin:0 auto;padding:16px 25px 36px}.head{margin-bottom:18px}h1{font-size:31px;line-height:1.05;margin:0;font-weight:800}.bolt{font-size:42px;vertical-align:-5px;margin-right:7px}.sub{font-size:18px;color:#8d98b1;margin-top:8px}.card{background:#111a2d;border:1px solid #273653;border-radius:25px;padding:25px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.metric{background:#0a1223;border-radius:17px;padding:18px;min-height:92px}.k{font-size:18px;line-height:1.15}.v{font-size:25px;font-weight:800;margin-top:4px;white-space:nowrap}.modes{display:grid;grid-template-columns:1fr 1fr 1.25fr;gap:14px;margin-top:17px}.btn{height:54px;border:0;border-radius:15px;padding:0 22px;color:#fff;font-weight:800;font-size:17px;background:#245b91;white-space:nowrap;cursor:pointer}.green{background:#00a65a}.red{background:#b52f45}.gray{background:#273753}.modes .btn:first-child{background:#293954}.note,.status{color:#9ba5ba}.note{font-size:17px;margin-top:15px}.row{display:flex;gap:14px;align-items:center;margin-top:14px}.label{font-size:16px;font-weight:800;color:#8d98b1;margin:15px 0 7px}.input{height:54px;background:#091122;border:1px solid #30405e;border-radius:15px;color:#edf2ff;padding:0 17px;font-size:18px;outline:none;width:100%;min-width:0}.input::placeholder{color:#7f899d;opacity:1}.control{padding-top:22px}.profit{display:flex;gap:14px;align-items:center}.profit .input{flex:1}.check{font-size:18px;display:flex;align-items:center;gap:9px;white-space:nowrap}.check input{width:27px;height:27px;accent-color:#1676e8}.main{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(0,1.55fr) minmax(0,1fr);gap:10px;margin-top:14px}.main .btn{padding:0 10px}.off{display:flex;align-items:center;gap:14px;margin-top:14px}.off .btn{width:147px}.session{font-size:17px;color:#9ba5ba}.status{font-size:14px;min-height:18px;margin-top:8px}.title{font-size:28px;font-weight:800;margin-bottom:18px}.badge{display:inline-block;background:#b52f45;color:#fff;border-radius:14px;padding:8px 16px;font-size:14px;font-weight:800;margin-bottom:14px}.pos{display:flex;flex-direction:column;gap:10px}.item{background:#0a1223;border-radius:14px;padding:12px 14px;font-size:14px}.empty{color:#8d96a9;font-size:17px}.slots{display:grid;grid-template-columns:1fr 1fr;gap:12px}.slot{height:52px;background:#091122;border:1px solid #30405e;border-radius:14px;color:#8d96a9;padding:0 16px;font-size:17px;width:100%}@media(max-width:560px){.wrap{padding:0 14px 32px}.head{margin-bottom:0}.bolt{font-size:34px}.sub{font-size:16px;white-space:nowrap}.card{padding:14px;margin-bottom:10px}.control{padding:5px 14px}.grid{gap:8px}.metric{padding:5px 10px;min-height:61px}.k{font-size:17px}.v{font-size:25px}.modes{gap:8px;margin-top:9px}.btn{height:42px;font-size:15px;padding:0 7px}.modes .btn{font-size:14px;height:54px}.note{font-size:15px;margin-top:9px}.label{font-size:10px;margin:6px 0 2px}.row{gap:8px;margin-top:8px}.input{height:38px;padding:0 12px;font-size:16px}.profit{gap:8px}.check{font-size:15px;gap:6px}.check input{width:17px;height:17px}#allocation + .btn{flex:0 0 147px}.control .row:nth-of-type(2) .btn{flex:0 0 102px}.profit .input{flex:0 0 205px}.main{gap:8px;margin-top:5px}.main .btn{padding:0 4px;font-size:13px;height:38px}.off{gap:8px;margin-top:5px}.off .btn{width:83px;height:38px;font-size:14px}.session{font-size:14px}.status{display:block;font-size:11px;min-height:13px;margin-top:0}.title{font-size:28px;margin-bottom:12px}.badge{padding:6px 10px;font-size:11px}.empty{font-size:15px}.slots{gap:8px}.slot{height:38px;font-size:14px}}
</style></head><body><div class="wrap"><div class="head"><h1><span class="bolt">⚡</span>Fast Scalper Beta</h1><div class="sub">Version 0.01 REPAIR PAPER · Trading TF: 3m</div></div>
<section class="card"><div class="grid"><div class="metric"><div class="k">Account Balance</div><div class="v" id="account">1850.0000</div></div><div class="metric"><div class="k">Bot Balance</div><div class="v" id="bot">0.0000</div></div><div class="metric"><div class="k">Reserve</div><div class="v" id="reserve">0.0000</div></div><div class="metric"><div class="k">Session PnL</div><div class="v" id="pnl">0.0000</div></div></div><div class="modes"><button class="btn" onclick="setMode('PAPER')">PAPER</button><button class="btn" onclick="setMode('BINANCE_TEST')">BINANCE<br>TEST</button><button class="btn" onclick="testBinance()">TEST BINANCE</button></div><div class="note" id="note">Bot balance set: 0.0000 USDT</div></section>
<section class="card control"><div class="label">BOT BALANCE · USDT</div><div class="row" style="margin-top:0"><input id="allocation" class="input" inputmode="decimal" placeholder="150"><button class="btn" onclick="setAllocation()">SET BOT BALANCE</button></div><div class="label">WITHDRAW AMOUNT · USDT</div><div class="row" style="margin-top:0"><input id="withdraw" class="input" inputmode="decimal" placeholder="0.00"><button class="btn red" onclick="doWithdraw()">WITHDRAW</button></div><div class="label">PROFIT TARGET · %</div><div class="profit"><input id="profit" class="input" inputmode="decimal" value="0.33"><label class="check"><input id="reinvest" type="checkbox" checked> Reinvest</label></div><div class="main"><button class="btn green" onclick="startBot()">BOT ON · ACTIVE</button><button class="btn red" onclick="emergencyStop()">EMERGENCY</button><button class="btn gray" onclick="resetBot()">RESET</button></div><div class="off"><button class="btn red" onclick="stopBot()">BOT OFF</button><div class="session" id="session">SESSION 00:00 · 24H 00:00</div></div><div class="status" id="status"></div></section>
<section class="card"><div class="title">Open Positions</div><div id="badge" class="badge">BOT OFF · TRADING STOPPED</div><div class="pos" id="positions"><div class="empty">No open positions.</div></div></section><section class="card"><div class="title">Rotation Pool · TOP-20</div><div class="slots" id="slots"></div></section></div>
<script>
const $=id=>document.getElementById(id),num=x=>Number(x||0).toFixed(4),age=s=>{s=Math.max(0,Math.floor(Number(s||0)));return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s%3600/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')},api=async(p,o={})=>{const r=await fetch(p,{cache:'no-store',headers:{'Content-Type':'application/json',...(o.headers||{})},...o});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||d.error||('HTTP '+r.status));return d},msg=t=>{const e=$('status');e.textContent=t||'';e.style.display=t?'block':'none'};
async function refresh(){try{const s=await api('/api/state');$('account').textContent=num(s.account);$('bot').textContent=num(s.bot_balance);$('reserve').textContent=num(s.reserve);$('pnl').textContent=num(s.session_realized);$('profit').value=Number(s.profit_pct??.33).toFixed(2);$('reinvest').checked=!!s.reinvest;$('session').textContent='SESSION '+age(s.session_age)+' · 24H '+age(s.day_age);$('note').textContent='Bot balance set: '+num(s.bot_balance)+' USDT';$('badge').textContent=s.running?'BOT ON · ACTIVE':'BOT OFF · TRADING STOPPED';$('badge').style.background=s.running?'#00a65a':'#b52f45';drawSlots(s.slots||[]);drawPos(s.positions||[]);if(s.error)msg(s.error)}catch(e){msg(e.message)}}
function drawSlots(a){const e=$('slots');if(e.children.length!==20){e.innerHTML='';for(let i=0;i<20;i++){const x=document.createElement('input');x.className='slot';x.placeholder='USDT pair';x.onchange=saveSlots;e.appendChild(x)}}[...e.children].forEach((x,i)=>x.value=a[i]||'')}
let saveTimer;function saveSlots(){clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{const a=[...$('slots').children].map(x=>x.value.trim().toUpperCase()).filter(Boolean);await api('/api/slots',{method:'POST',body:JSON.stringify({slots:a,profit_pct:Number($('profit').value.replace(',','.'))||.33,reinvest:$('reinvest').checked})});msg('Rotation Pool saved')}catch(e){msg(e.message)}},250)}
function drawPos(a){const e=$('positions');if(!a.length){e.innerHTML='<div class="empty">No open positions.</div>';return}e.innerHTML=a.map(p=>'<div class="item"><b>'+p.symbol+'</b> · stake '+num(p.stake)+' · PnL '+num(p.delta_usdt)+' · '+age(p.age_seconds)+'</div>').join('')}
async function setMode(m){try{await api('/api/mode',{method:'POST',body:JSON.stringify({mode:m})});msg('Mode set: '+m);refresh()}catch(e){msg(e.message)}}async function testBinance(){try{const d=await api('/api/test-binance',{method:'POST'});msg(d.message||'Binance Testnet connection OK')}catch(e){msg(e.message)}}async function setAllocation(){try{await api('/api/allocation',{method:'POST',body:JSON.stringify({amount:Number($('allocation').value.replace(',','.'))})});msg('Bot balance set');refresh()}catch(e){msg(e.message)}}async function doWithdraw(){try{await api('/api/withdraw',{method:'POST',body:JSON.stringify({amount:Number($('withdraw').value.replace(',','.'))||0})});$('withdraw').value='';msg('Withdraw completed');refresh()}catch(e){msg(e.message)}}async function startBot(){try{await api('/api/paper/start',{method:'POST',body:JSON.stringify({profit_pct:Number($('profit').value.replace(',','.'))||0,reinvest:$('reinvest').checked})});msg('Bot active');refresh()}catch(e){msg(e.message)}}async function stopBot(){try{await api('/api/paper/stop',{method:'POST'});msg('Bot OFF — new entries stopped');refresh()}catch(e){msg(e.message)}}async function emergencyStop(){try{await api('/api/paper/emergency',{method:'POST'});msg('Emergency stop completed');refresh()}catch(e){msg(e.message)}}async function resetBot(){try{await api('/api/reset',{method:'POST'});msg('Reset completed');refresh()}catch(e){msg(e.message)}}refresh();setInterval(refresh,1000);
</script></body></html>'''

for r in list(legacy.app.router.routes):
    if getattr(r,'path',None)=='/' and 'GET' in (getattr(r,'methods',set()) or set()): legacy.app.router.routes.remove(r)
@legacy.app.get('/',response_class=HTMLResponse)
async def approved_ui_home():
    r=HTMLResponse(HTML);r.headers['Cache-Control']='no-store, no-cache, must-revalidate, max-age=0';r.headers['Pragma']='no-cache';r.headers['Expires']='0';return r
